import{_ as a,c as s,o as n,a5 as e}from"./chunks/framework.DorIfSpC.js";const p="/images/ai-video-cost-5s.png",b=JSON.parse('{"title":"那張 AI 影片比價表，少了一列","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://blog.aidream.com.tw/project/ai-video-cost-selfhost"}],["meta",{"property":"og:url","content":"https://blog.aidream.com.tw/project/ai-video-cost-selfhost"}],["meta",{"property":"og:title","content":"那張 AI 影片比價表，少了一列 | 星智未來"}],["meta",{"name":"twitter:title","content":"那張 AI 影片比價表，少了一列 | 星智未來"}],["meta",{"property":"og:type","content":"article"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"那張 AI 影片比價表，少了一列\\",\\"description\\":\\"\\",\\"url\\":\\"https://blog.aidream.com.tw/project/ai-video-cost-selfhost\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"url\\":\\"https://blog.aidream.com.tw\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://blog.aidream.com.tw/logo.svg\\"}},\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://blog.aidream.com.tw/project/ai-video-cost-selfhost\\"}}"]]},"headers":[],"relativePath":"project/ai-video-cost-selfhost.md","filePath":"project/ai-video-cost-selfhost.md","lastUpdated":1787542547000}'),r={name:"project/ai-video-cost-selfhost.md"};function o(i,t,d,l,h,c){return n(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="那張-ai-影片比價表-少了一列" tabindex="-1">那張 AI 影片比價表，少了一列 <a class="header-anchor" href="#那張-ai-影片比價表-少了一列" aria-label="Permalink to &quot;那張 AI 影片比價表，少了一列&quot;">​</a></h1><blockquote><p>做 5 秒 AI 影片要多少錢：八個方案、一台租來的顯卡，和一個我算錯又改回來的數字</p></blockquote><p><strong>作者</strong>：Ray <strong>日期</strong>：2026 年 8 月 22 日</p><hr><p>社群上流傳一張比價表，整理得很清楚：八個方案，統一用「生成 5 秒影片」計價。 出處是<a href="https://www.facebook.com/share/p/1FkQGuCJsa/" target="_blank" rel="noreferrer">董宇凡的臉書貼文</a>，標題叫「我快要變 AI 比價王了」。</p><table tabindex="0"><thead><tr><th>平台</th><th>模型</th><th>年費</th><th>720P／支</th><th>480P／支</th></tr></thead><tbody><tr><td>大陸即夢</td><td>Seedance 2.5</td><td>24,893</td><td>44.2</td><td>20.4</td></tr><tr><td>國際即夢</td><td>Seedance 2.5</td><td>21,419</td><td>37.7</td><td>17.4</td></tr><tr><td>Higgsfield</td><td>Seedance 2.5 Fast</td><td>67,522</td><td>20</td><td>10</td></tr><tr><td>LibTV</td><td>Seedance 2.5</td><td>57,439</td><td>16.56</td><td>7.2</td></tr><tr><td>大陸即夢</td><td>Seedance 2.0 Fast</td><td>24,893</td><td>8.5</td><td>不提供</td></tr><tr><td>國際即夢</td><td>Seedance 2.0 Fast</td><td>21,419</td><td>20.3</td><td>不提供</td></tr><tr><td>Higgsfield</td><td>Seedance 2.0 Fast</td><td>67,522</td><td>11.25</td><td>5</td></tr><tr><td>LibTV</td><td>Seedance 2.0 Fast VIP</td><td>57,439</td><td>7.92</td><td>3.6</td></tr></tbody></table><p>（單位新台幣，統計日 2026-08-11，資料整理：董宇凡）</p><p>看完我第一個念頭不是「哪個便宜」，是<strong>這張表沒有自架那一列。</strong></p><p>因為我剛好有數字。</p><hr><h2 id="先看清楚這張表在說什麼" tabindex="-1">先看清楚這張表在說什麼 <a class="header-anchor" href="#先看清楚這張表在說什麼" aria-label="Permalink to &quot;先看清楚這張表在說什麼&quot;">​</a></h2><p>每一列有<strong>兩個</strong>價格，不是一個。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>入場費   年付 21,419 到 67,522</span></span>
<span class="line"><span>單價     每支 3.6 到 44.2</span></span></code></pre></div><p><strong>年費是最便宜的那幾格的代價。</strong> LibTV 的 480P 每支 3.6 元，全表最低——但你要先付 57,439。</p><p>Higgsfield 的 480P 每支 5 元，年費 67,522，是全表最貴的入場費。</p><p>反過來，即夢的年費只要兩萬出頭，但每支 17 到 20 元。</p><p><strong>這是一張「先付多少換每支便宜多少」的表，不是一張價目表。</strong></p><hr><h2 id="我的數字" tabindex="-1">我的數字 <a class="header-anchor" href="#我的數字" aria-label="Permalink to &quot;我的數字&quot;">​</a></h2><p>過去兩週我在 <a href="https://runpod.io?ref=s3bs0r0v" target="_blank" rel="noreferrer">RunPod</a> 上跑 MiniMax H3，是開源權重、自己在 ComfyUI 部署。這幾筆是實際計時，不是估的。</p><p><strong>全部都是 768 × 1376，也就是 1.06 MP</strong> ——這件事等一下很重要：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>480P 直式   480 × 854   = 0.41 MP</span></span>
<span class="line"><span>720P 直式   720 × 1280  = 0.92 MP</span></span>
<span class="line"><span>我跑的      768 × 1376  = 1.06 MP    ← 比 720P 多 15% 像素</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2026-08-14   RTX 5090   $0.99/hr</span></span>
<span class="line"><span>             5 秒、10 步                    73 秒</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2026-08-21   L40S       $0.99/hr</span></span>
<span class="line"><span>             8.0 秒（192 影格）、20 步     561.02 秒</span></span>
<span class="line"><span>             9.4 秒（226 影格）、20 步     717.25 秒</span></span>
<span class="line"><span>             15.1 秒（362 影格）、20 步   1604.30 秒</span></span>
<span class="line"><span>             9.4 秒、8 步 ＋ turbo LoRA    416.48 秒</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2026-08-21   RTX PRO 6000  $2.12/hr</span></span>
<span class="line"><span>             5.2 秒（124 影格）、20 步      270 秒</span></span></code></pre></div><p>要跟那張表比，得全部換算成 5 秒。而換算需要一個係數。</p><hr><h2 id="那個係數我算錯了一次" tabindex="-1">那個係數我算錯了一次 <a class="header-anchor" href="#那個係數我算錯了一次" aria-label="Permalink to &quot;那個係數我算錯了一次&quot;">​</a></h2><p>影片生成的成本<strong>不是隨長度線性成長</strong>——注意力的計算量隨序列長度平方成長，所以片子越長，每一格越貴。</p><p>我一開始用 L40S 的三個點去算，得到指數 <strong>1.65</strong>。</p><p>然後我把它拿去外推別台機器，得到一個不合理的結論：一張 $2.12/hr 的卡跟一張 $0.99/hr 的卡一樣快。</p><p>不合理的結果通常代表資料有問題。回頭看，果然：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>00001   362 影格  1604.30 秒   ← 這是那台機器上的第一支，含載入 46 GB 權重</span></span>
<span class="line"><span>00002   192 影格   561.02 秒   ← 模型已在記憶體</span></span>
<span class="line"><span>00003   226 影格   717.25 秒</span></span></code></pre></div><p><strong>我拿第一支去算，而它被載入時間灌了水。</strong> 灌的是分子，指數就被高估。</p><p>只用兩支乾淨的重算，得到 1.51。再對照 8 月 14 號 5090 那組（5 秒 73 秒、15 秒約 300 秒）得到 1.32。</p><p><strong>取 1.4 當工作值。</strong></p><p>這件事本身沒什麼了不起，但它是自架才會遇到的：<strong>你看得到每一支的計時、看得到哪一支是第一支、知道模型什麼時候被載入。</strong> 用 API 的話，你只會拿到一個總價。</p><hr><h2 id="換算成-5-秒" tabindex="-1">換算成 5 秒 <a class="header-anchor" href="#換算成-5-秒" aria-label="Permalink to &quot;換算成 5 秒&quot;">​</a></h2><p>用 k = 1.4，匯率抓 32：</p><table tabindex="0"><thead><tr><th>設定</th><th>5 秒所需</th><th>每支</th></tr></thead><tbody><tr><td>RTX 5090、10 步</td><td>73 秒（實測）</td><td><strong>NT$0.6</strong></td></tr><tr><td>L40S、8 步 ＋ turbo</td><td>約 180 秒（外推）</td><td><strong>NT$1.6</strong></td></tr><tr><td>L40S、20 步</td><td>約 304 秒（外推）</td><td><strong>NT$2.7</strong></td></tr><tr><td>RTX PRO 6000、20 步</td><td>270 秒（實測）</td><td><strong>NT$5.1</strong></td></tr></tbody></table><p>⚠️ 三件事要說清楚，不然這張表會騙人：</p><p><strong>一、5090 那筆是 10 步，其他是 20 步。</strong> 步數少一半，品質不同，不能直接比。它是這條線的下限，不是常態。</p><p><strong>二、PRO 6000 那筆疑似含載入時間。</strong> 它看起來比 L40S 貴一倍，但那張卡實際上更快——那筆數字大概被同一個問題灌水了。<strong>我把它留在表上，因為它是實測值，但它不可信。</strong></p><p><strong>三、外推的兩格是外推的。</strong> 我沒有真的跑過 5 秒的 L40S。</p><p><strong>最誠實的一格是 L40S、20 步、NT$2.7。</strong> 那是同一台機器上跑過三個長度、係數自己量出來、模型已載入的條件下算的。</p><hr><h2 id="跟那張表放在一起——但要比對的欄位" tabindex="-1">跟那張表放在一起——但要比對的欄位 <a class="header-anchor" href="#跟那張表放在一起——但要比對的欄位" aria-label="Permalink to &quot;跟那張表放在一起——但要比對的欄位&quot;">​</a></h2><p>這裡差點被我自己搞錯。</p><p>我跑的是 1.06 MP，<strong>比 720P 還高</strong>。所以要比的是 720P 那一欄，不是最便宜的 480P 那欄。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>720P／支              自架（1.06 MP，比 720P 更高）</span></span>
<span class="line"><span>────────────────      ──────────────────────────</span></span>
<span class="line"><span>大陸即夢 2.5   44.2      L40S 20 步        NT$2.7</span></span>
<span class="line"><span>國際即夢 2.5   37.7      L40S 8 步＋turbo  NT$1.6</span></span>
<span class="line"><span>Higgsfield 2.5  20</span></span>
<span class="line"><span>LibTV 2.5      16.56</span></span>
<span class="line"><span>Higgsfield 2.0  11.25</span></span>
<span class="line"><span>大陸即夢 2.0     8.5</span></span>
<span class="line"><span>LibTV 2.0 VIP   7.92     ← 全表 720P 最低</span></span></code></pre></div><p><strong>全表 720P 最便宜的是 7.92，還要先付 57,439 的年費。</strong></p><p>自架同樣畫質是 2.7，年費零。<strong>單價不到三分之一。</strong></p><p>而且這還沒往下調。480P 的像素只有我現在的四成，理論上還能再省一半以上——<strong>但那我沒測過，所以不寫進表裡。</strong></p><p>那損益兩平在哪裡？<strong>不存在。</strong> 自架同時贏了兩個欄位。</p><hr><h2 id="但最乾淨的對照不是那張表" tabindex="-1">但最乾淨的對照不是那張表 <a class="header-anchor" href="#但最乾淨的對照不是那張表" aria-label="Permalink to &quot;但最乾淨的對照不是那張表&quot;">​</a></h2><p>拿自架去比 Seedance，永遠會被問一句：模型不同、畫質不同，怎麼比？</p><p>有一個對照沒有這個問題——<strong>MiniMax H3 自己就有官方 API。</strong></p><p>同一個模型，同一份權重，只差誰的機器：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MiniMax H3 官方 API      768P   $0.08／秒   →  5 秒 $0.40  ≈  NT$12.8</span></span>
<span class="line"><span>自架 L40S、20 步          768P               →  5 秒        ≈  NT$2.7</span></span>
<span class="line"><span>自架 L40S、8 步 ＋ turbo  768P               →  5 秒        ≈  NT$1.6</span></span></code></pre></div><p>（官方定價 2026-08-16，<a href="https://leadde.ai/zh-Hant/blog/mini-max-h3-pricing" target="_blank" rel="noreferrer">來源</a>）</p><p>而且解析度剛好對上，不是「差不多」：<strong>我跑的 768 × 1376 就是 768P，跟官方 API 同一檔。</strong></p><p><strong>便宜 4.7 倍。</strong> 用 8 步加速的設定是 8 倍。</p><p><img src="`+p+`" alt="做 5 秒 AI 影片要多少錢：加上自架那一列"></p><p>這個結論看起來太漂亮了，所以下面要講它漏掉了什麼。</p><hr><h2 id="這個算法沒有算進去的東西" tabindex="-1">這個算法沒有算進去的東西 <a class="header-anchor" href="#這個算法沒有算進去的東西" aria-label="Permalink to &quot;這個算法沒有算進去的東西&quot;">​</a></h2><p><strong>一、失敗率。</strong></p><p>上面每一支都是「成功的那一支」的成本。實際上不是每一支都能用。</p><p>我這兩天有些鏡頭要跑三到五支才有一支可用——那類鏡頭的真實成本要乘三到五倍。</p><p><strong>但這一項對兩邊是公平的。</strong> 官方 API 的定價頁自己就寫著：</p><blockquote><p>失敗或被拒絕的生成仍會計費。實際製作成本應按「每部可用影片的成本」而非單純每秒費率計算。</p></blockquote><p><strong>這句話對自架一樣成立。</strong> 差別只在於自架失敗一次是 NT$2.7，API 失敗一次是 NT$12.8。</p><p><strong>二、你的時間。</strong></p><p>租機器要開機、下模型、接工作流、上傳素材。我實測從開新機器到能按下執行，十分鐘以內——其中下載 74.3 GB 只花 1 分 53 秒，<strong>瓶頸不在下載，在設定。</strong></p><p>十分鐘乘上 $0.99/hr 是 NT$5.3。但那十分鐘你也在，那不是機器的錢。</p><p><strong>三、忘記關機。</strong></p><p>這是自架真正的風險。那張表上的年費是固定的，你不會多付；一台開著的機器會一直計費。</p><p>我這次還踩到一個小坑：RunPod 的 network volume <strong>即使 Pod 關機也繼續計費</strong>，$0.015/hr，一個月約 NT$346。</p><p>它省下的是每次開機的十分鐘設定。<strong>換句話說，一個月開不到十次，那個 volume 就不划算。</strong></p><p><strong>四、學習曲線。</strong></p><p>這是最大的一項，而且我沒辦法幫你算。</p><p>上面那些數字，是我知道要選容器記憶體 133 GiB 的卡、要抓剪枝 INT8 的權重、要把 duration 填 10.8 才會得到 260 影格之後的數字。</p><p><strong>第一天不會長這樣。</strong> 我第一次租機器的時候，有一整個上午在讀錯的記憶體數字。</p><hr><h2 id="選卡-看記憶體-不是看價格" tabindex="-1">選卡：看記憶體，不是看價格 <a class="header-anchor" href="#選卡-看記憶體-不是看價格" aria-label="Permalink to &quot;選卡：看記憶體，不是看價格&quot;">​</a></h2><p>順帶一個實測出來的判準，因為它會直接改變成本。</p><p>H3 的權重不放在顯示卡裡，是整份留在系統記憶體，需要的部分才搬進去。所以<strong>決定你跑不跑得動的是容器記憶體，不是 VRAM。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RTX 5090      55.88 GiB    328 影格就 OOM</span></span>
<span class="line"><span>L40S         133.2 GiB    362 影格還有兩倍半餘裕</span></span>
<span class="line"><span>RTX PRO 6000    175 GiB    充裕</span></span></code></pre></div><p>而且<strong>卡片上標的 RAM 不等於容器上限</strong>。L40S 頁面寫 94 GB，實際量到 133.2 GiB，多了四成。開機第一件事是：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/fs/cgroup/memory/memory.limit_in_bytes</span></span></code></pre></div><p><strong>不要用 <code>free -g</code></strong>——容器裡的 <code>free</code> 顯示的是整台實體機，那是鄰居的儀表。</p><p>還有一條反直覺的：貴的卡不一定划算。8 月 14 號那次量到，一張 $2.89/hr 的 H100 PCIe 只比 $0.99/hr 的 5090 快 10% 到 30%。</p><p><strong>大機器買的是記憶體，不是速度。</strong></p><hr><h2 id="但這張表真正沒辦法定價的是別的" tabindex="-1">但這張表真正沒辦法定價的是別的 <a class="header-anchor" href="#但這張表真正沒辦法定價的是別的" aria-label="Permalink to &quot;但這張表真正沒辦法定價的是別的&quot;">​</a></h2><p>上面全部都在比每支多少錢。那是這張表的框架，我照著它比了。</p><p>可是我這兩天最有價值的發現，一項都不在價格欄裡：</p><p><strong>影片模型會照時間戳執行。</strong> 你寫「At 00:05.500 切到近景」，它就在 5.5 秒切。我寫一份精確到 0.1 秒、有九個節拍的表演腳本，它九拍全中。</p><p><strong>但長度會毀掉這個能力。</strong> 同一份腳本，跑 226 影格全中，跑 362 影格全部跳過，而且最後兩秒崩成噪訊。</p><p>那個發現值多少錢？它讓我知道<strong>表演鏡頭的長度上限</strong>。不知道的話，我會反覆重跑一個註定失敗的設定，一次 26 分鐘。</p><p><strong>這種東西不會寫在文件裡，也不會出現在 API 的參數列表上。</strong> 它只出現在你能改提示詞、能立刻重跑、能看每一支計時的環境裡。</p><p>那張表在比「一支多少錢」。自架真正買到的是<strong>你知道自己在買什麼</strong>。</p><hr><h2 id="所以" tabindex="-1">所以 <a class="header-anchor" href="#所以" aria-label="Permalink to &quot;所以&quot;">​</a></h2><p>如果你的用途是「偶爾生幾支，畫質要好，不想碰技術」——那張表是對的，挑一格付錢就好，你省下的時間比省下的錢值錢。</p><p>如果你要長期做、要量、要調、要知道為什麼這支不行——</p><p><strong>同一個模型，自己跑比官方 API 便宜 4.7 倍。每支 NT$2.7，年費零，第一天的帳單是 $2。</strong></p><p>想自己試一個下午：<a href="https://runpod.io?ref=s3bs0r0v" target="_blank" rel="noreferrer">RunPod</a>。</p><hr><p><em>比價表資料來源：<a href="https://www.facebook.com/share/p/1FkQGuCJsa/" target="_blank" rel="noreferrer">董宇凡的臉書貼文</a>，統計日 2026-08-11。 MiniMax H3 官方 API 定價來源：<a href="https://leadde.ai/zh-Hant/blog/mini-max-h3-pricing" target="_blank" rel="noreferrer">leadde.ai</a>，2026-08-16。 本文只引用該表作為對照，自架部分的數字全部是我自己的實測。</em></p><p><em>本文的實測環境為 RunPod 租用之 RTX 5090、L40S、RTX PRO 6000 Blackwell 與 H100 PCIe， 模型為 MiniMax H3 剪枝 INT8 開源權重，於 ComfyUI 部署，輸出一律 768 × 1376（1.06 MP）。 比價表的統計日為 2026-08-11， 我的計時為 2026-08-14 與 08-21。匯率以 32 計。</em></p><p><em>本文的 RunPod 連結為推薦連結，透過它註冊我會獲得少量回饋，不影響你的價格。</em></p><p><em><a href="https://aidream.com.tw" target="_blank" rel="noreferrer">aidream.com.tw</a></em></p>`,113)])])}const u=a(r,[["render",o]]);export{b as __pageData,u as default};
